int32_t g_coreType = 0; // mix = 0; cube = 1; vec = 2;
int32_t g_matmulCount = 0;
std::map<std::string, uint64_t>& GetArgVal()
{
    static std::map<std::string, uint64_t> instance;
    return instance;
}

int32_t g_taskRation = 2;
